const types=new Set(['heading','paragraph','read_aloud','gm_note','list','media']);
export function validateComposition(value,board){if(!Array.isArray(value)||value.length>100)throw Error('Composition must contain at most 100 blocks');return value.map((b,index)=>{if(!b||typeof b!=='object'||Array.isArray(b)||!types.has(b.type))throw Error('Unknown block at '+index);const fields=b.type==='media'?['type','assetId','caption']:b.type==='list'?['type','items']:b.type==='heading'?['type','text','level']:['type','text'];if(Object.keys(b).some(k=>!fields.includes(k)))throw Error('Unknown block field');if(b.type==='media'){if(!board.assets?.some(a=>a.id===b.assetId))throw Error('Media must reference an already selected source asset');if(b.caption!==undefined&&(typeof b.caption!=='string'||b.caption.length>1000))throw Error('Invalid caption')}else if(b.type==='list'){if(!Array.isArray(b.items)||b.items.length>50||b.items.some(t=>typeof t!=='string'||t.length>4000))throw Error('Invalid list')}else{if(typeof b.text!=='string'||b.text.length>10000)throw Error('Invalid block text');if(b.type==='heading'&&![2,3,4].includes(b.level??3))throw Error('Heading level must be 2, 3 or 4')}return structuredClone(b)})}
export function proposeComposition({board,cardId,lens,currentComposition,blocks}){if(!board.cards.some(c=>c.id===cardId))throw Error('Missing target card');return {kind:'prototype_composition_proposal_v1',boardId:board.id,sourcePin:board.pin,cardId,lens,base:JSON.stringify(currentComposition??null),blocks:validateComposition(blocks,board),authority:'operator_authored_adaptation'}}
export function applyComposition(proposal,{board,cardId,lens,currentComposition}){if(proposal.boardId!==board.id||proposal.sourcePin!==board.pin||proposal.cardId!==cardId||proposal.lens!==lens||proposal.base!==JSON.stringify(currentComposition??null))throw Error('Composition proposal is stale or belongs to another target');return validateComposition(proposal.blocks,board)}
export function compositionFromText(text){return text.split(/\n\s*\n/).filter(Boolean).map(text=>({type:'paragraph',text}))}
const escape=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function inlineText(text){return escape(text).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>')}
export function renderComposition(blocks,board){return validateComposition(blocks,board).map(b=>{if(b.type==='heading'){const level=b.level??3;return `<h${level}>${inlineText(b.text)}</h${level}>`}if(b.type==='list')return '<ul>'+b.items.map(t=>'<li>'+inlineText(t)+'</li>').join('')+'</ul>';if(b.type==='media'){const a=board.assets.find(a=>a.id===b.assetId);if(!a.url.startsWith('/private/'))throw Error('Unsafe selected asset URL');return `<figure class="composed-media"><img src="${escape(a.url)}" alt="${escape(b.caption??a.title)}"><figcaption>${escape(b.caption??a.title)} <small>GM reference · player-safe review pending · source page ${a.page+1}</small></figcaption></figure>`}if(b.type==='read_aloud'||b.type==='gm_note')return `<section class="composed-callout ${b.type}"><small>${b.type==='read_aloud'?'Read aloud · authored':'GM note'}</small><p>${inlineText(b.text)}</p></section>`;return '<p>'+inlineText(b.text)+'</p>'}).join('')}
